7	use crate::view::snapshot::{ForceKind, LandscapeSnapshot, SnapshotComponent, SnapshotForce, SnapshotResidue};
8	
9	pub(crate) fn force_kind_attr(kind: ForceKind) -> &'static str {
10	    match kind {
11	        ForceKind::Stressor => "stressor",
12	        ForceKind::Purpose => "purpose",
13	    }
14	}
15	
16	/// `S-<shortname>` / `P-<shortname>` — the operator-facing label for a force.
17	pub(crate) fn force_label(force: &SnapshotForce) -> String {
18	    let prefix = match force.kind {
19	        ForceKind::Stressor => "S",
20	        ForceKind::Purpose => "P",
21	    };
22	    format!("{prefix}-{}", force.shortname)
23	}
24	
25	/// Bucket an open-ended status string into the small set of known lifecycle
26	/// stages the UI styles distinctly; anything else falls back to "other" but
27	/// keeps its raw text in the tooltip.
28	pub(crate) fn status_bucket(status: &str) -> &'static str {
29	    match status {
30	        "proposed" => "proposed",
31	        "actual" => "actual",
32	        "deprecated" => "deprecated",
33	        _ => "other",
34	    }
35	}
36	
37	pub(crate) fn status_tooltip(status: &str) -> String {
38	    match status {
39	        "proposed" => "proposed — staged in the ledger, not yet built".to_string(),
40	        "actual" => "actual — implemented and present in the codebase".to_string(),
41	        "deprecated" => "deprecated — superseded, scheduled for removal".to_string(),
42	        other => format!("{other} — non-standard status"),
43	    }
44	}
45	
46	pub(crate) fn row_total(force_id: &str, residues: &[SnapshotResidue]) -> usize {
47	    residues
48	        .iter()
49	        .filter(|r| r.force_id == force_id && r.coupled)
50	        .count()
51	}
52	
53	pub(crate) fn col_total(component: &str, residues: &[SnapshotResidue]) -> usize {
54	    residues
55	        .iter()
56	        .filter(|r| r.component_id == component && r.coupled)
57	        .count()
58	}
59	
60	pub(crate) fn architecture_sets_for_force(
61	    force_id: &str,
62	    components: &[SnapshotComponent],
63	    residues: &[SnapshotResidue],
64	) -> String {
65	    let mut sets: Vec<&str> = residues
66	        .iter()
67	        .filter(|r| r.force_id == force_id && r.coupled)
68	        .filter_map(|r| {
69	            components
70	                .iter()
71	                .find(|c| c.name == r.component_id)
72	                .map(|c| c.architecture_set.as_str())
73	        })
74	        .collect();
75	    sets.sort_unstable();
76	    sets.dedup();
77	    sets.join(" ")
78	}
