80	/// Precomputed per-component header cell data (avoids recomputing inside the
81	/// `rsx!` for-loop body, which only accepts markup, not arbitrary statements).
82	struct HeaderCol<'a> {
83	    name: &'a str,
84	    status: &'a str,
85	    architecture_set: &'a str,
86	    tooltip: String,
87	    bucket: &'static str,
88	}
89	
90	/// Precomputed per-(force, component) coupling cell data.
91	struct MatrixCell<'a> {
92	    component_name: &'a str,
93	    coupled_attr: &'static str,
94	    body: &'static str,
95	}
96	
97	/// Precomputed per-force row data.
98	struct ForceRow<'a> {
99	    id: &'a str,
100	    kind: &'static str,
101	    arch: String,
102	    attractor_id: &'a str,
103	    search: String,
104	    total: usize,
105	    label: String,
106	    attractor_label: String,
107	    description: &'a str,
108	    naive_change: &'a str,
109	    outcomes: &'a str,
110	    cells: Vec<MatrixCell<'a>>,
111	}
112	
113	/// Precomputed per-component footer total.
114	struct FooterCol<'a> {
115	    name: &'a str,
116	    total: usize,
117	}
118	
119	/// Single unified table: sticky-left force column (accordion for full force
120	/// detail), sticky-top component header row (status dot + tooltip), sticky-
121	/// right row-totals column, sticky-bottom column-totals footer.
122	pub fn render_matrix(snapshot: &LandscapeSnapshot) -> String {
123	    let forces: Vec<&SnapshotForce> = snapshot
124	        .stressors
125	        .iter()
126	        .chain(snapshot.purposes.iter())
127	        .collect();
128	
129	    let header_cols: Vec<HeaderCol> = snapshot
130	        .components
131	        .iter()
132	        .map(|component| HeaderCol {
133	            name: &component.name,
134	            status: &component.status,
135	            architecture_set: &component.architecture_set,
136	            tooltip: status_tooltip(&component.status),
137	            bucket: status_bucket(&component.status),
138	        })
139	        .collect();
140	
141	    let force_rows: Vec<ForceRow> = forces
142	        .iter()
143	        .map(|force| {
144	            let kind = force_kind_attr(force.kind);
145	            let arch = architecture_sets_for_force(&force.id, &snapshot.components, &snapshot.residues);
146	            let search = format!(
147	                "{} {} {} {} {}",
148	                force.id, force.shortname, kind, force.attractor_id, arch
149	            );
150	            let label = force_label(force);
151	            let total = row_total(&force.id, &snapshot.residues);
152	            let attractor_label = snapshot
153	                .attractors
154	                .iter()
155	                .find(|a| a.id == force.attractor_id)
156	                .map(|a| format!("{} · {}", a.id, a.name))
157	                .unwrap_or_else(|| force.attractor_id.clone());
158	
159	            let cells: Vec<MatrixCell> = snapshot
160	                .components
161	                .iter()
162	                .map(|component| {
163	                    let residue = snapshot
164	                        .residues
165	                        .iter()
166	                        .find(|r| r.force_id == force.id && r.component_id == component.name);
167	                    let coupled = residue.map(|r| r.coupled).unwrap_or(false);
168	                    MatrixCell {
169	                        component_name: &component.name,
170	                        coupled_attr: if coupled { "1" } else { "0" },
171	                        body: if coupled { "1" } else { "" },
172	                    }
173	                })
174	                .collect();
175	
176	            ForceRow {
177	                id: &force.id,
178	                kind,
179	                arch,
180	                attractor_id: &force.attractor_id,
181	                search,
182	                total,
183	                label,
184	                attractor_label,
185	                description: &force.description,
186	                naive_change: &force.naive_change,
187	                outcomes: &force.outcomes,
188	                cells,
189	            }
190	        })
191	        .collect();
192	
193	    let footer_cols: Vec<FooterCol> = snapshot
194	        .components
195	        .iter()
196	        .map(|component| FooterCol {
197	            name: &component.name,
198	            total: col_total(&component.name, &snapshot.residues),
199	        })
200	        .collect();
201	    let grand_total: usize = footer_cols.iter().map(|c| c.total).sum();
202	
203	    let element = rsx! {
204	        table { class: "matrix",
205	            thead {
206	                tr {
207	                    th {
208	                        class: "sticky-col sticky-row corner",
209	                        "data-sort-key": "force",
210	                        tabindex: "0",
211	                        role: "button",
212	                        "force"
213	                    }
214	                    for col in header_cols.iter() {
215	                        th {
216	                            class: "sticky-row",
217	                            "data-component": "{col.name}",
218	                            "data-status": "{col.status}",
219	                            "data-architecture-set": "{col.architecture_set}",
220	                            "data-sort-key": "component:{col.name}",
221	                            title: "{col.tooltip}",
222	                            tabindex: "0",
223	                            role: "button",
224	                            span { class: "status-dot status-{col.bucket}" }
225	                            "{col.name}"
226	                        }
227	                    }
228	                    th {
229	                        class: "sticky-row sticky-col-right corner",
230	                        "data-sort-key": "total",
231	                        "total"
232	                    }
233	                }
234	            }
235	            tbody {
236	                for row in force_rows.iter() {
237	                    tr {
238	                        class: "force-row",
239	                        "data-force-id": "{row.id}",
240	                        "data-force-kind": "{row.kind}",
241	                        "data-architecture-set": "{row.arch}",
242	                        "data-attractor-id": "{row.attractor_id}",
243	                        "data-search": "{row.search}",
244	                        "data-row-total": "{row.total}",
245	                        th {
246	                            class: "sticky-col",
247	                            "data-force-id": "{row.id}",
248	                            button {
249	                                r#type: "button",
250	                                class: "force-accordion-toggle",
251	                                "data-accordion-toggle": "true",
252	                                "aria-expanded": "false",
253	                                "{row.label}"
254	                            }
255	                            div {
256	                                class: "force-detail",
257	                                hidden: "true",
258	                                dl {
259	                                    dt { "id" }
260	                                    dd { "{row.id}" }
261	                                    dt { "attractor" }
262	                                    dd { "{row.attractor_label}" }
263	                                    dt { "description" }
264	                                    dd { "{row.description}" }
265	                                    dt { "naive change" }
266	                                    dd { "{row.naive_change}" }
267	                                    dt { "outcomes" }
268	                                    dd { "{row.outcomes}" }
269	                                }
270	                            }
271	                        }
272	                        for cell in row.cells.iter() {
273	                            td {
274	                                "data-residue-cell": "true",
275	                                "data-force-id": "{row.id}",
276	                                "data-component": "{cell.component_name}",
277	                                "data-coupled": "{cell.coupled_attr}",
278	                                "{cell.body}"
279	                            }
280	                        }
281	                        td {
282	                            class: "sticky-col-right",
283	                            "data-row-total": "{row.total}",
284	                            "{row.total}"
285	                        }
286	                    }
287	                }
288	            }
289	            tfoot {
290	                tr {
291	                    th { class: "sticky-col corner", "totals" }
292	                    for col in footer_cols.iter() {
293	                        td {
294	                            "data-col-total": "{col.total}",
295	                            "data-component": "{col.name}",
296	                            "{col.total}"
297	                        }
298	                    }
299	                    td {
300	                        class: "sticky-col-right corner",
301	                        "data-grand-total": "{grand_total}",
302	                        "{grand_total}"
303	                    }
304	                }
305	            }
306	        }
307	    };
308	
309	    dioxus_ssr::render_element(element)
310	}
